-- Independent synthetic tenant. Every row and authority change is rolled back.
select pg_temp.actor('owner');
insert into core.tenants(id,name,slug,created_by) values(pg_temp.fid('billing-t'),'Synthetic Billing','wave5-billing-synthetic',pg_temp.fid('owner'));
insert into billing.tenant_subscriptions(tenant_id,plan_code,status,seats) values(pg_temp.fid('billing-t'),'starter','active',5);
insert into core.memberships(id,tenant_id,user_id,status) values(pg_temp.fid('billing-member'),pg_temp.fid('billing-t'),pg_temp.fid('owner'),'active');
insert into core.roles(id,tenant_id,code,name,requires_mfa) values(pg_temp.fid('billing-role'),pg_temp.fid('billing-t'),'synthetic-admin','Synthetic billing administrator',true);
insert into core.role_permissions values(pg_temp.fid('billing-t'),pg_temp.fid('billing-role'),'billing.synthetic.manage');
insert into core.role_permissions values(pg_temp.fid('billing-t'),pg_temp.fid('billing-role'),'billing.read');
insert into core.role_assignments(tenant_id,membership_id,role_id,created_by) values(pg_temp.fid('billing-t'),pg_temp.fid('billing-member'),pg_temp.fid('billing-role'),pg_temp.fid('owner'));
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(pg_temp.fid('owner-factor'),pg_temp.fid('owner'),'totp','verified',now(),now());
create function pg_temp.schedule_trial(cmd text,seat_count integer default 2,starts timestamptz default now()) returns jsonb language sql as $$
 select api.schedule_synthetic_subscription(pg_temp.fid('billing-t'),pg_temp.fid(cmd),pg_temp.fid(cmd),now(),1,'starter',seat_count,starts,starts+interval '1 day')$$;
select throws_ok($$select pg_temp.schedule_trial('trial')$$,'42501','SYNTHETIC_TARGET_REQUIRED','No tenant is automatically allowlisted');
insert into intelligence_control.synthetic_tenants values(pg_temp.fid('billing-t'),true);
select is(api.wave5_subscription_authorize(pg_temp.fid('billing-t')),pg_temp.fid('owner'),'Subscription recovery binds actual MFA actor');
select is(api.get_wave5_subscription(pg_temp.fid('billing-t'))->>'version','1','Native subscription read preserves exact revision');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fid('owner'),'role','authenticated','aal','aal1')::text,true);
select throws_ok($$select pg_temp.schedule_trial('trial')$$,'42501','Permission denied or multi-factor authentication required.','Synthetic changes need privileged MFA');
select pg_temp.actor('owner');
create temporary table w5_trial as select pg_temp.schedule_trial('trial') receipt;
do $$begin for i in 1..100 loop perform pg_temp.schedule_trial('trial');end loop;end$$;
select is((select count(*) from intelligence_control.subscription_revisions where tenant_id=pg_temp.fid('billing-t')),1::bigint,'100 schedule retries produce one immutable revision');
select is((select status from billing.tenant_subscriptions where tenant_id=pg_temp.fid('billing-t')),'active','Scheduling does not activate a trial');
select throws_ok($$select pg_temp.schedule_trial('trial',3)$$,'22023','IDEMPOTENCY_MISMATCH','Changed subscription retry denied');
create temporary table w5_future_trial as select pg_temp.schedule_trial('future',2,now()+interval '1 day') receipt;
select pg_temp.worker();
select throws_ok($$select api.apply_synthetic_subscription(pg_temp.fid('billing-t'),(select receipt#>>'{entity,id}' from w5_future_trial)::uuid)$$,'22023','NOT_EFFECTIVE','Future trial does not activate early');
delete from auth.mfa_factors where id=pg_temp.fid('owner-factor');
select throws_ok($$select api.apply_synthetic_subscription(pg_temp.fid('billing-t'),(select receipt#>>'{entity,id}' from w5_trial)::uuid)$$,'42501','PERMISSION_DENIED','Worker rechecks live privileged actor MFA');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(pg_temp.fid('owner-factor'),pg_temp.fid('owner'),'totp','verified',now(),now());
create temporary table w5_trial_activation as select api.apply_synthetic_subscription(pg_temp.fid('billing-t'),(select receipt#>>'{entity,id}' from w5_trial)::uuid) result;
do $$begin for i in 1..100 loop perform api.apply_synthetic_subscription(pg_temp.fid('billing-t'),(select receipt#>>'{entity,id}' from w5_trial)::uuid);end loop;end$$;
select is((select count(*) from intelligence_control.subscription_activations where tenant_id=pg_temp.fid('billing-t')),1::bigint,'100 worker retries activate once');
select is((select version from billing.tenant_subscriptions where tenant_id=pg_temp.fid('billing-t')),2::bigint,'Existing billing row has one optimistic revision increment');
select is((select status from billing.tenant_subscriptions where tenant_id=pg_temp.fid('billing-t')),'trialing','Explicit synthetic trial is authoritative');
select ok((select trial_started_at=now() and trial_ends_at=now()+interval '1 day' from billing.tenant_subscriptions where tenant_id=pg_temp.fid('billing-t')),'Trial preserves exact explicit half-open dates');
select is((select count(*) from core.command_receipts where tenant_id=pg_temp.fid('billing-t') and command_name='billing.synthetic.activate'),1::bigint,'Activation retains one existing authoritative receipt');
select is((select count(*) from audit.events where tenant_id=pg_temp.fid('billing-t') and event_type='billing.synthetic.activate'),1::bigint,'Activation records original actor and trusted worker audit');
insert into core.memberships(id,tenant_id,user_id,status) values(pg_temp.fid('billing-reader'),pg_temp.fid('billing-t'),pg_temp.fid('reader'),'active');
select throws_ok($$insert into core.memberships(id,tenant_id,user_id,status) values(pg_temp.fid('billing-outsider'),pg_temp.fid('billing-t'),pg_temp.fid('outsider'),'active')$$,'54000','SEAT_QUOTA_EXCEEDED','Seat admission checks existing authoritative cap');
select throws_ok($$update intelligence_control.subscription_revisions set seats=3 where tenant_id=pg_temp.fid('billing-t')$$,'55000','IMMUTABLE_EVIDENCE','Effective decision revisions cannot be edited');
select ok(not has_function_privilege('authenticated','api.apply_synthetic_subscription(uuid,uuid)','execute'),'Desktop cannot impersonate subscription worker');
select ok(not has_table_privilege('authenticated','intelligence_control.synthetic_tenants','insert'),'Client cannot allowlist real subscriptions');
update billing.plan_entitlements set enabled=true,numeric_limit=100 where plan_code='starter' and entitlement_code='quota.ai.tokens';
select ok(api.wave5_reserve_usage(pg_temp.fid('billing-t'),pg_temp.fid('billing-usage'),'ai.tokens',now(),now()+interval '1 day','1') is not null,'Metering uses explicit trial start instead of row creation');
select pg_temp.actor('owner');
select throws_ok($$select pg_temp.schedule_trial('stale')$$,'40001','VERSION_CONFLICT','Stale expected billing version denied');
create temporary table w5_subscription_wire as select api.get_wave5_subscription(pg_temp.fid('billing-t')) result;
select pg_temp.worker();
select is((select count(*) from core.memberships where tenant_id=pg_temp.fid('billing-t')),2::bigint,'Denied admission has zero membership effect');
